class Solution {
  public long distantSubarrays(int[] nums, int goal, int k) {
    int n = nums.length;
    long totalPairs = (long) n * (n + 1) / 2;
    if (k == 0) return totalPairs;
    long[] prefix = new long[n + 1];
    for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + nums[i];
    long[] sorted = prefix.clone();
    java.util.Arrays.sort(sorted);
    int m = 0;
    for (int i = 0; i <= n; i++) if (i == 0 || sorted[i] != sorted[i - 1]) sorted[m++] = sorted[i];
    long lo = (long) goal - k + 1, hi = (long) goal + k - 1;
    long[] bit = new long[m + 2];
    long close = 0;
    for (int j = 0; j <= n; j++) {
      if (j > 0) {
        // earlier prefix P[i] with lo <= P[j] - P[i] <= hi  =>  P[j] - hi <= P[i] <= P[j] - lo
        int a = lowerBound(sorted, m, prefix[j] - hi),
            b = lowerBound(sorted, m, prefix[j] - lo + 1);
        close += query(bit, b) - query(bit, a);
      }
      int rank = java.util.Arrays.binarySearch(sorted, 0, m, prefix[j]) + 1;
      for (int p = rank; p <= m; p += p & -p) bit[p]++;
    }
    return totalPairs - close;
  }

  private static int lowerBound(long[] a, int m, long x) {
    int lo = 0, hi = m;
    while (lo < hi) {
      int mid = (lo + hi) >>> 1;
      if (a[mid] < x) lo = mid + 1;
      else hi = mid;
    }
    return lo;
  }

  private static long query(long[] bit, int i) {
    long s = 0;
    for (; i > 0; i -= i & -i) s += bit[i];
    return s;
  }
}
